// Shared OPS-NO-INLINE-INTERPRETER fixture table (#2442 slice 1). Each row is a command, the gate decision
// (`deny`) and the `ceiling` flag. A ceiling row is allowed by the gate: its form sits where the gate does not
// read (quotes, a substitution, a payload, a heredoc body, a pipe into an interpreter, incomplete input).
// check-retro-tooling reports every denied and every ceiling row, and no other row.
// The differential test accepts a row that origin/main 99bb8b3ce denies and the head allows only when it is
// listed here with `ceiling: true`.

const deny = (command) => ({ command, deny: true, ceiling: false });
const allow = (command) => ({ command, deny: false, ceiling: false });
const ceiling = (command) => ({ command, deny: false, ceiling: true });

